const ScrollToTop = () => {
  return (
    <a href="#" className="scrollToTop">
      <i className="fa-solid fa-arrow-up-long"></i>
      <span className="pluse_1"></span>
      <span className="pluse_2"></span>
    </a>
  );
};

export default ScrollToTop;
